-- Seed 2 : 141 exercices de plus pour la bibliothèque de base (même source et même principe que le seed 1).
-- Données : supabase/seed/exercises.json ; images : public/exercises/<id>/{0,1}.jpg.

insert into public.muscu_exercises (id, user_id, name, primary_group, secondary_groups, image_path, is_custom)
select md5('riseup:exercise:' || v.src)::uuid, u.id, v.name, v.primary_group::public.muscle_group, v.secondary_groups, v.image_path, false
from auth.users u
cross join (values
    ('Wide-Grip_Barbell_Bench_Press', 'Développé couché barre prise large', 'pecs', array['epaules','triceps']::public.muscle_group[], 'Wide-Grip_Barbell_Bench_Press/0.jpg'),
